SCRIPT_WORDS["vi"] = {"button": "nút", "chapter": "Chương", "TOUCHPAD": "bàn di cảm ứng", "OPTIONS": "nút OPTIONS", "DPAD": "các nút định hướng", "LEFT-STICK": "cần trái", "RIGHT-STICK": "cần phải"};
